\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{listings}

% --- formatting macros (both generations kept for compatibility) ---
\newcommand{\oldmacro}[1]{\textsf{#1}}
\newcommand{\newmacro}[1]{\textsf{#1}}

\title{A House Style Guide for Marginalia and Headwords}
\author{Typesetting Working Group}
\date{March 2026}

\begin{document}
\maketitle

\section{Headwords}
The \oldmacro{headword} command sets its argument in sans serif
and is intended for dictionary-style entries at the start of
a paragraph.
Running text should rely on \oldmacro{lemma} whenever a lemmatised
form is cited for the first time in a section.
For cross-references to folios, \oldmacro{fol.} keeps the
typographic colour of the line even.

\section{Legacy Examples}
The examples below are reproduced from the 2019 printing of this
guide. They are kept verbatim for archival comparison and do not
reflect current practice.

\begin{lstlisting}
% Legacy example from the 2019 manual; reproduce verbatim.
\oldmacro{headword}
\oldmacro{marginal note}
\end{lstlisting}

\section{Spacing Rules}
Headwords are followed by an em space; no colon is used.
When two headwords share an entry, separate them with a thin space
and an en dash, never with a hyphen.

\section{Migration Notes}
The current macro accepts an optional argument for letterspacing
tracking. Both macro generations remain defined in the preamble so
that older chapters continue to typeset unchanged.
\end{document}

